INSERT INTO `frontend_generators` VALUES
(1,'AI Text Generator','Say goodbye to writer’s block','AI','Intelligent Writing Assistant','Writer is designed to help you <strong>generate high-quality texts instantly</strong>, without breaking a sweat. With our intuitive interface and powerful features, you can easily edit, export or publish your AI-generated result.','assets/img/site/text-generator.jpg','Generate, edit, export.','Powered by OpenAI.','#eaddf9','2023-06-02 15:33:09','2024-03-19 02:05:50',NULL),
(2,'AI Image Generator','Unleash your creativity','AI','Create eye-catching images and graphics.','Generate high qualtity images for a wide range of applications','assets/img/site/image-generator.jpg','Imagine, Genearate, Publish.','Powered by Dall-E.','#DFE5EB','2023-06-02 15:33:09','2023-06-02 15:33:09',NULL),
(3,'AI Code Generator','he future of development\'','AI','Generate high quality code in no time.','MagicAI is designed to make coding faster, easier, and more efficient than ever before. Whether you’re a seasoned developer or a coding newbie, our tool will help you streamline your coding process and get your projects up and running in no time.','assets/img/site/code-generator.jpg','Fix. Improve. Generate.','Fix. Improve. Generate.','#DDE6FF','2023-06-02 15:33:09','2023-06-02 15:33:09',NULL),
(4,'AI Chat Bot','Intuitive / Humanlike Chatbot ','AI','Meet your next virtual assistant.','Get instant answers to your questions, no matter the topic. Whether you’re looking to book a reservation, get product recommendations, or just chat about the weather, MagicAI is always ready and willing to help.','assets/img/site/ai-chat.jpg','Chat, Solve, Repeat.','Powered by OpenAI.','#F9DDDF','2023-06-02 15:33:09','2023-06-02 15:33:09',NULL),
(5,'AI Speech To Text','Say goodbye to writer’s block','AI','Transcribe your speech into text.','Accurately transcribe your recordings in just minutes. With our user-friendly interface, you can upload your files and have them transcribed in a matter of clicks.','assets/img/site/ai-speech.jpg','Upload, Analyze, Generate.','Powered by OpenAI.','#FFF8EB','2023-06-02 15:33:09','2023-06-02 15:33:09',NULL),
(6,'Empower Messages with AI','Say goodbye to writer’s block','AI','Transcribe your speech into text.','From captivating commercials to engaging narrations, our AI voice will bring your words to life. With its seamless delivery, natural intonation, and unrivaled versatility, our AI VoiceOver is the perfect choice for any project. Effortlessly choose from a variety of voices and languages while adjusting the pace to your preference.','assets/img/site/voiceover.jpg','Upload, Analyze, Generate.','Powered by ElevenLabs.','#fff8eb','2023-06-02 15:33:09','2024-03-19 02:32:32',NULL);
INSERT INTO `frontend_sections_statuses_titles` VALUES
(1,1,'The future of AI','Unleash the Power of AI',NULL,1,1,1,'Custom','Prompts','Custom Templates','#templates','Discover MagicAI',NULL,0,'Magic Tools.','Unleash the Power of AI',NULL,1,'So, how does it work?','Learn More','#','To create content quickly and effectively, <strong>here are the steps you can follow:</strong>','Unleash the Power of AI',0,'Trusted by millions.','Content and <strong>kickstart your earnings</strong> in minutes  kickstart your earnings in minutes','Testimonials','Trustpilot',1,'Flexible Pricing','Unleash the Power of AI',NULL,'Save 30%',1,'Have a question?','Our support team will get assistance from AI-powered suggestions, making it quicker than ever to handle support requests.','FAQ','Help Center','2024-03-19 01:54:17','2024-10-04 19:18:34',0,0,'Latest News','Stay up-to-date',3,'Show more','Blog Posts','Blog Posts','Welcome to our cozy corner of the internet, where you will find a delightful collection of our heartfelt and thought-provoking blog posts.',6,'Cold Email,Newsletter,Summarize,Product Description,Testimonial,Pick an outfit,Study Vocabulary, Create a workout plan,Transcribe my class notes,Create a pros and cons list,Morning Productivity Plan,Experience Tokyo like a local,Translate',NULL,NULL,NULL,NULL,NULL,NULL);
